mapper.select:
SELECT ro.id, ro.order_no, ro.title, ro.urgency, ro.status, CASE ro.status WHEN 'PENDING' THEN '待处理' WHEN 'ASSIGNED' THEN '已派单' WHEN 'ACCEPTED' THEN '已接单' WHEN 'IN_PROGRESS' THEN '处理中' WHEN 'SUSPENDED' THEN '已挂起' WHEN 'COMPLETED' THEN '已完成' WHEN 'CONFIRMED' THEN '已确认' WHEN 'EVALUATED' THEN '已评价' WHEN 'ESCALATED' THEN '已升级' WHEN 'REWORK' THEN '返工中' WHEN 'REJECTED' THEN '已拒绝' ELSE ro.status END AS status_desc, c.name AS community_name, b.name AS building_name, ro.unit_number, cat.name AS category_name, worker.real_name AS worker_name, ro.rework_count, ro.created_at FROM repair_order ro LEFT JOIN community c ON ro.community_id = c.id LEFT JOIN building b ON ro.building_id = b.id LEFT JOIN category cat ON ro.category_id = cat.id LEFT JOIN sys_user worker ON ro.current_worker_id = worker.id
AND ro.status = #{status}
AND ro.community_id = #{communityId}
AND ro.category_id = #{categoryId}
AND (ro.title LIKE CONCAT('%', #{keyword}, '%') OR ro.description LIKE CONCAT('%', #{keyword}, '%') OR ro.order_no LIKE CONCAT('%', #{keyword}, '%'))
AND ro.owner_id = #{ownerId}
AND ro.current_worker_id = #{workerId}
AND ro.created_at >= #{startDate}
AND ro.created_at <= #{endDate}
ORDER BY ro.created_at DESC

SELECT COUNT(*)
FROM repair_order
WHERE current_worker_id = #{workerId}
AND status IN

    #{status}
